steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(filter: {
        team: { name: { eq: \"Web\" } },
        creator: { name: { eq: \"Omar Haddad\" } },
        createdAt: { gte: \"2025-09-10T00:00:00.000Z\", lte: \"2025-09-10T23:59:59.999Z\" }
      }) {
        nodes {
          id
          title
          description
          createdAt
          assignee { id name }
          creator { id name }
          team { id name }
        }
      }
    }"
  }'
